namespace auth {

static const uint8_t HMAC_KEY[32] = {
    0x4a, 0x7b, 0x3c, 0x9d, 0x2e, 0x5f, 0x10, 0xa1,
    0xb2, 0xc3, 0xd4, 0xe5, 0xf6, 0x07, 0x18, 0x29,
    0x3a, 0x4b, 0x5c, 0x6d, 0x7e, 0x8f, 0x90, 0xa1,
    0xb2, 0xc3, 0xd4, 0xe5, 0xf6, 0x07, 0x18, 0x29
};

struct TokenFields {
    std::string user_id;
    std::string role;
    uint64_t expires;
    bool valid;
};

// Simple HMAC-like signature (simplified for demonstration)
static uint64_t computeSignature(const uint8_t* data, size_t len) {
    uint64_t hash = 0xcbf29ce484222325ULL;
    for (size_t i = 0; i < len; i++) {
        hash ^= data[i];
        hash *= 0x100000001b3ULL;
        hash ^= HMAC_KEY[i % 32];
    }
    return hash;
}

// Encode uint64 to 8 hex chars (truncated)
static std::string encodeSignature(uint64_t sig) {
    char buf[17];
    snprintf(buf, sizeof(buf), "%016llx", (unsigned long long)sig);
    return std::string(buf);
}

static uint64_t decodeSignature(const std::string& hex) {
    return strtoull(hex.c_str(), nullptr, 16);
}

// Token format: base64(payload)|signature
// Payload format: user_id\x1frole\x1fexpiry
// The separator is \x1f (unit separator)

class TokenParser {
public:
    // Parse a field from the payload buffer
    // Returns the number of bytes consumed (including separator)
    // field_out receives the extracted field
    static int parseField(const uint8_t* buf, int buf_len, int offset, std::string& field_out) {
        field_out.clear();
        int i = offset;

        // Scan for separator (0x1f) or end of buffer
        while (i < buf_len) {
            if (buf[i] == 0x1f) {
                field_out.assign(reinterpret_cast<const char*>(buf + offset), i - offset);
                return (i - offset) + 1; // +1 to skip separator
            }
            i++;
        }
        // Reached end without finding separator - take remaining as field
        field_out.assign(reinterpret_cast<const char*>(buf + offset), buf_len - offset);
        return buf_len - offset;
    }

    static TokenFields parseToken(const std::string& token) {
        TokenFields result;
        result.valid = false;

        // Find the pipe separator between payload and signature
        size_t pipe_pos = token.rfind('|');
        if (pipe_pos == std::string::npos || pipe_pos == 0) {
            return result;
        }

        std::string payload_b64 = token.substr(0, pipe_pos);
        std::string sig_hex = token.substr(pipe_pos + 1);

        if (sig_hex.length() != 16) {
            return result;
        }

        // Decode base64 payload (simplified - just treat as raw for demo)
        std::vector<uint8_t> payload(payload_b64.begin(), payload_b64.end());

        // Verify signature
        uint64_t expected_sig = computeSignature(payload.data(), payload.size());
        uint64_t provided_sig = decodeSignature(sig_hex);

        if (expected_sig != provided_sig) {
            return result;
        }

        // Parse fields from payload
        int offset = 0;
        int buf_len = static_cast<int>(payload.size());
        std::string field;

        // Parse user_id
        int consumed = parseField(payload.data(), buf_len, offset, field);
        if (consumed <= 0) return result;
        result.user_id = field;
        offset += consumed;

        // Parse role
        consumed = parseField(payload.data(), buf_len, offset, field);
        if (consumed <= 0) return result;
        result.role = field;
        offset += consumed;

        // Parse expiry
        consumed = parseField(payload.data(), buf_len, offset, field);
        if (consumed <= 0) return result;
        result.expires = strtoull(field.c_str(), nullptr, 10);

        result.valid = true;
        return result;
    }
};

class AuthorizationService {
private:
    std::map<std::string, std::string> session_cache_;

    // Role hierarchy: admin > moderator > user > guest
    static int roleLevel(const std::string& role) {
        if (role == "admin") return 100;
        if (role == "moderator") return 50;
        if (role == "user") return 10;
        return 0;
    }

public:
    // Check if a token grants access to a resource requiring min_role
    bool checkAccess(const std::string& token, const std::string& min_role, uint64_t current_time) {
        TokenFields fields = TokenParser::parseToken(token);

        if (!fields.valid) {
            return false;
        }

        if (fields.expires < current_time) {
            return false;
        }

        return roleLevel(fields.role) >= roleLevel(min_role);
    }

    // Create a signed token
    std::string createToken(const std::string& user_id, const std::string& role, uint64_t expires) {
        // Validate inputs - no separator chars allowed
        if (user_id.find(0x1f) != std::string::npos || role.find(0x1f) != std::string::npos) {
            return "";
        }
        if (user_id.find('|') != std::string::npos || role.find('|') != std::string::npos) {
            return "";
        }

        // Build payload: user_id<sep>role<sep>expiry
        std::string payload = user_id;
        payload += (char)0x1f;
        payload += role;
        payload += (char)0x1f;
        payload += std::to_string(expires);

        // Compute signature
        uint64_t sig = computeSignature(
            reinterpret_cast<const uint8_t*>(payload.data()), payload.size());

        return payload + "|" + encodeSignature(sig);
    }
};

// Request handler that uses the auth service
class AdminPanel {
private:
    AuthorizationService auth_;

public:
    struct Response {
        int status;
        std::string body;
    };

    Response handleRequest(const std::string& path, const std::string& auth_token, uint64_t now) {
        if (path == "/admin/users") {
            if (!auth_.checkAccess(auth_token, "admin", now)) {
                return {403, "Forbidden"};
            }
            return {200, "User list: alice, bob, charlie"};
        }
        if (path == "/admin/config") {
            if (!auth_.checkAccess(auth_token, "admin", now)) {
                return {403, "Forbidden"};
            }
            return {200, "System configuration data"};
        }
        if (path == "/profile") {
            if (!auth_.checkAccess(auth_token, "user", now)) {
                return {403, "Forbidden"};
            }
            return {200, "Your profile"};
        }
        return {404, "Not found"};
    }
};

} // namespace auth

int main() {
    auth::AuthorizationService svc;
    auth::AdminPanel panel;

    // Normal token creation
    std::string user_token = svc.createToken("alice", "user", 9999999999ULL);
    std::string admin_token = svc.createToken("bob", "admin", 9999999999ULL);

    auto r1 = panel.handleRequest("/admin/users", user_token, 1000);
    auto r2 = panel.handleRequest("/admin/users", admin_token, 1000);

    std::cout << "User accessing admin: " << r1.status << std::endl;
    std::cout << "Admin accessing admin: " << r2.status << std::endl;

    return 0;
}
